<?php
require_once dirname(__DIR__).'/includes/auth.php';$u=require_role('coordinator','administrator');$type=(string)($_GET['type']??'projects');$allowed=['projects','supervisors','submissions','evaluations'];if(!in_array($type,$allowed,true))$type='projects';$scoped=$u['role']==='coordinator'&&!empty($u['department_id']);$params=$scoped?[$u['department_id']]:[];
if($type==='projects'){$title='Project status report';$sql='SELECT p.reference_no,p.title,p.status,d.name department,s.name session_name FROM projects p JOIN departments d ON d.id=p.department_id JOIN academic_sessions s ON s.id=p.academic_session_id'.($scoped?' WHERE p.department_id=?':'').' ORDER BY d.name,p.title';$headers=['Reference'=>'reference_no','Title'=>'title','Department'=>'department','Session'=>'session_name','Status'=>'status'];}
elseif($type==='supervisors'){$title='Supervisor workload report';$sql='SELECT u.first_name,u.last_name,u.staff_number,COUNT(DISTINCT ps.project_id) active_projects FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN project_supervisors ps ON ps.supervisor_id=u.id AND ps.ended_at IS NULL LEFT JOIN projects p ON p.id=ps.project_id WHERE r.name="supervisor"'.($scoped?' AND u.department_id=?':'').' GROUP BY u.id ORDER BY u.last_name';$headers=['Supervisor'=>'first_name','Staff number'=>'staff_number','Active projects'=>'active_projects'];}
elseif($type==='submissions'){$title='Submission report';$sql='SELECT p.reference_no,p.title,s.document_type,s.status,s.submitted_at,u.first_name,u.last_name FROM submissions s JOIN projects p ON p.id=s.project_id JOIN users u ON u.id=s.student_id'.($scoped?' WHERE p.department_id=?':'').' ORDER BY s.submitted_at DESC';$headers=['Reference'=>'reference_no','Project'=>'title','Document'=>'document_type','Student'=>'first_name','Status'=>'status','Date'=>'submitted_at'];}
else{$title='Evaluation report';$sql='SELECT p.reference_no,p.title,u.first_name,u.last_name,e.total_score,e.status,e.submitted_at FROM evaluations e JOIN projects p ON p.id=e.project_id JOIN users u ON u.id=e.evaluator_id'.($scoped?' WHERE p.department_id=?':'').' ORDER BY e.submitted_at DESC';$headers=['Reference'=>'reference_no','Project'=>'title','Evaluator'=>'first_name','Score'=>'total_score','Status'=>'status','Date'=>'submitted_at'];}
$q=db()->prepare($sql);$q->execute($params);$rows=$q->fetchAll();$pageTitle=$title;$crumbTrail=['Reports'];require dirname(__DIR__).'/includes/header.php';
?>
<section class="card filter-bar mb-3"><div class="filter-form"><div class="seg-tabs" role="tablist"><?php foreach($allowed as $t): ?><a class="seg-tab <?= $type===$t?'is-active':'' ?>" href="<?= e(url('coordinator/reports.php?type='.$t)) ?>"><?= e(ucfirst($t)) ?></a><?php endforeach; ?></div><label class="search-box ms-2"><?= ui_icon('search') ?><input type="search" class="form-control" placeholder="Search records..." aria-label="Search report" data-live-filter="#reportTable tbody tr"></label><button class="btn btn-outline-primary ms-auto" onclick="window.print()">Print report</button></div></section>
<section class="card p-4"><div class="section-row mb-3"><h2 class="section-heading mb-0"><?= e($title) ?></h2><span class="text-muted small"><?= count($rows) ?> record<?= count($rows)===1?'':'s' ?></span></div><div class="table-responsive"><table class="table table-soft" id="reportTable"><thead><tr><?php foreach($headers as $h=>$k): ?><th><?= e($h) ?></th><?php endforeach; ?></tr></thead><tbody>
<?php foreach($rows as $r): ?><tr><?php foreach($headers as $h=>$k): $val=(string)($r[$k]??'—'); ?><td><?php if($k==='first_name'): ?><?= e(trim($val.' '.($r['last_name']??''))) ?><?php elseif($k==='status'&&$val!=='—'): ?><?= ui_pill($val) ?><?php elseif(str_ends_with($k,'_at')&&$val!=='—'): ?><?= e(ui_date($val)) ?><?php elseif($k==='document_type'&&$val!=='—'): ?><?= e(ui_doc_label($val)) ?><?php else: ?><?= e($val) ?><?php endif; ?></td><?php endforeach; ?></tr><?php endforeach; ?>
<?php if(!$rows): ?><tr><td colspan="<?= count($headers) ?>"><div class="empty-state">No records available for this report.</div></td></tr><?php endif; ?></tbody></table></div></section>
<?php require dirname(__DIR__).'/includes/footer.php'; ?>
